import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Send, Bot, CheckCircle, XCircle, Instagram, Facebook,
  Linkedin, Twitter, Youtube, MessageCircle, Zap, Database,
  Settings, BarChart3, Workflow, FileText, Image as ImageIcon,
  Mail, Globe, Shield, Rocket, TrendingUp, Clock, AlertCircle,
  Play, Pause, RefreshCw, Plus, Search, Bell, User, LogOut,
  ChevronRight, ChevronDown, Copy, Download, Upload, Trash2,
  Edit3, Eye, EyeOff, Lock, Unlock, Star, Heart, Share2,
  MessageSquare, Users, Calendar, Tag, Hash, Link2, Code,
  Terminal, Cpu, MemoryStick, HardDrive, Cloud, Server,
  Activity, Gauge, Layers, GitBranch, GitMerge, GitCommit,
  ArrowRight, ArrowDown, Check, X, Loader2, Sparkles,
  Target, Award, Flame, Zap as ZapIcon, Circle, Square,
  Triangle, Hexagon, Octagon, Diamond
} from 'lucide-react';

// ============================================================
// SOCIAL MEDIA CONTENT AUTOMATION SYSTEM - COMPLETE BUILD
// ============================================================

const App = () => {
  const [activeView, setActiveView] = useState('dashboard');
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [notifications, setNotifications] = useState(12);
  const [systemStatus, setSystemStatus] = useState('active');
  const [selectedPlatform, setSelectedPlatform] = useState(null);
  const [contentQueue, setContentQueue] = useState([
    { id: 1, title: 'Nuevo producto lanzado 🚀', platform: 'Instagram', status: 'pending', time: '14:30', type: 'post' },
    { id: 2, title: 'Tips de productividad', platform: 'LinkedIn', status: 'approved', time: '15:00', type: 'article' },
    { id: 3, title: 'Behind the scenes', platform: 'YouTube', status: 'processing', time: '16:00', type: 'video' },
    { id: 4, title: 'Oferta especial 50%', platform: 'Facebook', status: 'scheduled', time: '17:30', type: 'promo' },
    { id: 5, title: 'Tutorial rápido', platform: 'Twitter', status: 'published', time: '12:00', type: 'thread' },
  ]);
  const [agents, setAgents] = useState([
    { id: 'router', name: 'Social Media Router', status: 'active', tasks: 156, efficiency: 98 },
    { id: 'creator', name: 'AI Content Creator', status: 'active', tasks: 89, efficiency: 95 },
    { id: 'approver', name: 'Approval Agent', status: 'active', tasks: 45, efficiency: 100 },
    { id: 'publisher', name: 'Publishing Router', status: 'active', tasks: 67, efficiency: 97 },
    { id: 'telegram', name: 'Telegram Parser', status: 'active', tasks: 34, efficiency: 92 },
    { id: 'analyzer', name: 'Analytics Agent', status: 'idle', tasks: 12, efficiency: 88 },
  ]);
  const [telegramMessages, setTelegramMessages] = useState([
    { id: 1, text: '🎉 ¡Gran noticia! Acabamos de lanzar nuestra nueva línea de productos sostenibles. Hechos con materiales 100% reciclados y diseñados para durar.', time: '14:25', processed: true },
    { id: 2, text: ' Datos interesantes: El 73% de los consumidores prefieren marcas con compromiso ambiental. ¿Y tú?', time: '14:20', processed: true },
    { id: 3, text: '🔥 Tips de productividad: 1. Planifica tu día 2. Prioriza tareas 3. Toma descansos 4. Celebra logros', time: '14:15', processed: false },
    { id: 4, text: '💡 Sabías que... La automatización de contenido puede ahorrar hasta 20 horas semanales a los creadores de contenido.', time: '14:10', processed: false },
  ]);
  const [metrics, setMetrics] = useState({
    totalPosts: 1247,
    approved: 1189,
    published: 1156,
    failed: 33,
    engagement: 45.2,
    reach: 128400,
    conversions: 892,
    tokenUsage: 2847563,
    costSaved: 4520,
    uptime: 99.97
  });
  const [workflowNodes, setWorkflowNodes] = useState([
    { id: 'input', x: 50, y: 100, label: 'Input Source', icon: 'message', status: 'active' },
    { id: 'router', x: 250, y: 100, label: 'Router Agent', icon: 'bot', status: 'active' },
    { id: 'rag', x: 250, y: 220, label: 'RAG Knowledge', icon: 'database', status: 'active' },
    { id: 'memory', x: 250, y: 340, label: 'Agent Memory', icon: 'memory', status: 'active' },
    { id: 'generator', x: 450, y: 100, label: 'Content Generator', icon: 'sparkles', status: 'active' },
    { id: 'approval', x: 650, y: 100, label: 'Email Approval', icon: 'mail', status: 'pending' },
    { id: 'image', x: 650, y: 220, label: 'Image Generator', icon: 'image', status: 'idle' },
    { id: 'publisher', x: 850, y: 100, label: 'Publishing Router', icon: 'globe', status: 'idle' },
    { id: 'platforms', x: 1050, y: 100, label: 'Multi-Platform', icon: 'share', status: 'idle' },
  ]);
  const [activeWorkflowStep, setActiveWorkflowStep] = useState(0);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [newContent, setNewContent] = useState({ title: '', platform: 'Instagram', type: 'post', content: '' });
  const [darkMode, setDarkMode] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedAgent, setSelectedAgent] = useState(null);
  const [logs, setLogs] = useState([
    { time: '14:32:15', type: 'info', message: 'Router Agent processed new request from Telegram' },
    { time: '14:32:16', type: 'success', message: 'Content generated successfully (247 tokens)' },
    { time: '14:32:17', type: 'info', message: 'Email approval sent to admin@company.com' },
    { time: '14:32:18', type: 'warning', message: 'Rate limit approaching for Instagram API (85%)' },
    { time: '14:32:20', type: 'success', message: 'Image generated via Pollinations.ai (1024x1024)' },
    { time: '14:32:22', type: 'info', message: 'Content queued for publishing at 15:00 UTC' },
    { time: '14:32:25', type: 'success', message: 'Backup saved to Google Drive: /posts/2024/' },
    { time: '14:32:28', type: 'error', message: 'Failed to connect to Twitter API - retrying in 30s' },
  ]);

  // Simulate workflow animation
  useEffect(() => {
    const interval = setInterval(() => {
      setActiveWorkflowStep(prev => (prev + 1) % workflowNodes.length);
    }, 2000);
    return () => clearInterval(interval);
  }, []);

  // Simulate metrics updates
  useEffect(() => {
    const interval = setInterval(() => {
      setMetrics(prev => ({
        ...prev,
        totalPosts: prev.totalPosts + Math.floor(Math.random() * 3),
        engagement: prev.engagement + (Math.random() - 0.5) * 0.5,
        reach: prev.reach + Math.floor(Math.random() * 500),
      }));
    }, 5000);
    return () => clearInterval(interval);
  }, []);

  const navItems = [
    { id: 'dashboard', label: 'Dashboard', icon: BarChart3 },
    { id: 'workflow', label: 'Workflow', icon: Workflow },
    { id: 'agents', label: 'Agentes IA', icon: Bot },
    { id: 'content', label: 'Contenido', icon: FileText },
    { id: 'telegram', label: 'Telegram Feed', icon: MessageCircle },
    { id: 'approval', label: 'Aprobaciones', icon: CheckCircle },
    { id: 'publishing', label: 'Publicación', icon: Globe },
    { id: 'analytics', label: 'Analytics', icon: TrendingUp },
    { id: 'settings', label: 'Configuración', icon: Settings },
  ];

  const platforms = [
    { id: 'instagram', name: 'Instagram', icon: Instagram, color: 'from-pink-500 to-purple-600', connected: true, posts: 342 },
    { id: 'facebook', name: 'Facebook', icon: Facebook, color: 'from-blue-500 to-blue-700', connected: true, posts: 289 },
    { id: 'linkedin', name: 'LinkedIn', icon: Linkedin, color: 'from-blue-600 to-blue-800', connected: true, posts: 156 },
    { id: 'twitter', name: 'Twitter/X', icon: Twitter, color: 'from-gray-700 to-gray-900', connected: true, posts: 423 },
    { id: 'youtube', name: 'YouTube', icon: Youtube, color: 'from-red-500 to-red-700', connected: true, posts: 67 },
    { id: 'threads', name: 'Threads', icon: MessageSquare, color: 'from-gray-800 to-black', connected: false, posts: 0 },
    { id: 'tiktok', name: 'TikTok', icon: Music, color: 'from-pink-500 to-cyan-500', connected: false, posts: 0 },
  ];

  return (
    <div className={`min-h-screen ${darkMode ? 'bg-gray-950 text-white' : 'bg-gray-50 text-gray-900'} transition-colors duration-300`}>
      {/* Animated Background */}
      <div className="fixed inset-0 overflow-hidden pointer-events-none">
        <div className="absolute top-0 left-1/4 w-96 h-96 bg-purple-600/10 rounded-full blur-3xl animate-pulse" />
        <div className="absolute bottom-0 right-1/4 w-96 h-96 bg-blue-600/10 rounded-full blur-3xl animate-pulse" style={{ animationDelay: '1s' }} />
        <div className="absolute top-1/2 left-1/2 w-96 h-96 bg-pink-600/5 rounded-full blur-3xl animate-pulse" style={{ animationDelay: '2s' }} />
      </div>

      <div className="relative flex h-screen">
        {/* Sidebar */}
        <motion.aside
          initial={false}
          animate={{ width: sidebarCollapsed ? 80 : 280 }}
          className={`${darkMode ? 'bg-gray-900/80 border-gray-800' : 'bg-white/80 border-gray-200'} border-r backdrop-blur-xl flex flex-col z-20`}
        >
          {/* Logo */}
          <div className={`p-4 ${sidebarCollapsed ? 'px-2' : ''} border-b ${darkMode ? 'border-gray-800' : 'border-gray-200'}`}>
            <div className="flex items-center gap-3">
              <motion.div
                whileHover={{ rotate: 180 }}
                transition={{ duration: 0.5 }}
                className="w-10 h-10 rounded-xl bg-gradient-to-br from-purple-600 to-blue-600 flex items-center justify-center flex-shrink-0"
              >
                <Zap className="w-6 h-6 text-white" />
              </motion.div>
              {!sidebarCollapsed && (
                <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
                  <h1 className="font-bold text-lg bg-gradient-to-r from-purple-400 to-blue-400 bg-clip-text text-transparent">
                    SocialAuto
                  </h1>
                  <p className="text-xs text-gray-500">v2.0 Pro</p>
                </motion.div>
              )}
            </div>
          </div>

          {/* Navigation */}
          <nav className="flex-1 p-3 space-y-1 overflow-y-auto">
            {navItems.map((item) => {
              const Icon = item.icon;
              const isActive = activeView === item.id;
              return (
                <motion.button
                  key={item.id}
                  whileHover={{ x: 4 }}
                  whileTap={{ scale: 0.95 }}
                  onClick={() => setActiveView(item.id)}
                  className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-xl transition-all ${
                    isActive
                      ? 'bg-gradient-to-r from-purple-600/20 to-blue-600/20 text-purple-400 border border-purple-500/30'
                      : darkMode ? 'text-gray-400 hover:bg-gray-800/50' : 'text-gray-600 hover:bg-gray-100'
                  } ${sidebarCollapsed ? 'justify-center' : ''}`}
                >
                  <Icon className="w-5 h-5 flex-shrink-0" />
                  {!sidebarCollapsed && <span className="text-sm font-medium">{item.label}</span>}
                  {item.id === 'approval' && !sidebarCollapsed && (
                    <span className="ml-auto bg-red-500 text-white text-xs px-2 py-0.5 rounded-full">3</span>
                  )}
                </motion.button>
              );
            })}
          </nav>

          {/* System Status */}
          <div className={`p-3 border-t ${darkMode ? 'border-gray-800' : 'border-gray-200'}`}>
            <div className={`flex items-center gap-2 px-3 py-2 rounded-lg ${darkMode ? 'bg-gray-800/50' : 'bg-gray-100'}`}>
              <div className={`w-2 h-2 rounded-full ${systemStatus === 'active' ? 'bg-green-500 animate-pulse' : 'bg-red-500'}`} />
              {!sidebarCollapsed && (
                <span className="text-xs text-gray-400">
                  Sistema {systemStatus === 'active' ? 'Activo' : 'Inactivo'}
                </span>
              )}
            </div>
          </div>
        </motion.aside>

        {/* Main Content */}
        <main className="flex-1 flex flex-col overflow-hidden">
          {/* Header */}
          <header className={`${darkMode ? 'bg-gray-900/50 border-gray-800' : 'bg-white/50 border-gray-200'} border-b backdrop-blur-xl px-6 py-4 flex items-center justify-between`}>
            <div className="flex items-center gap-4">
              <button
                onClick={() => setSidebarCollapsed(!sidebarCollapsed)}
                className={`p-2 rounded-lg ${darkMode ? 'hover:bg-gray-800' : 'hover:bg-gray-100'} transition-colors`}
              >
                <ChevronRight className={`w-5 h-5 transition-transform ${sidebarCollapsed ? '' : 'rotate-180'}`} />
              </button>
              <div>
                <h2 className="text-xl font-bold">
                  {navItems.find(n => n.id === activeView)?.label}
                </h2>
                <p className="text-sm text-gray-500">
                  {activeView === 'dashboard' && 'Vista general del sistema'}
                  {activeView === 'workflow' && 'Flujo de automatización'}
                  {activeView === 'agents' && 'Gestión de agentes IA'}
                  {activeView === 'content' && 'Cola de contenido'}
                  {activeView === 'telegram' && 'Feed de Telegram → Instagram'}
                  {activeView === 'approval' && 'Aprobaciones pendientes'}
                  {activeView === 'publishing' && 'Distribución multi-plataforma'}
                  {activeView === 'analytics' && 'Métricas y rendimiento'}
                  {activeView === 'settings' && 'Configuración del sistema'}
                </p>
              </div>
            </div>

            <div className="flex items-center gap-3">
              {/* Search */}
              <div className={`flex items-center gap-2 px-3 py-2 rounded-xl ${darkMode ? 'bg-gray-800/50' : 'bg-gray-100'}`}>
                <Search className="w-4 h-4 text-gray-500" />
                <input
                  type="text"
                  placeholder="Buscar..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="bg-transparent border-none outline-none text-sm w-48"
                />
              </div>

              {/* Notifications */}
              <button className={`relative p-2 rounded-xl ${darkMode ? 'bg-gray-800/50 hover:bg-gray-800' : 'bg-gray-100 hover:bg-gray-200'} transition-colors`}>
                <Bell className="w-5 h-5" />
                {notifications > 0 && (
                  <span className="absolute -top-1 -right-1 w-5 h-5 bg-red-500 text-white text-xs rounded-full flex items-center justify-center">
                    {notifications}
                  </span>
                )}
              </button>

              {/* Create Button */}
              <motion.button
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                onClick={() => setShowCreateModal(true)}
                className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-purple-600 to-blue-600 text-white rounded-xl font-medium text-sm shadow-lg shadow-purple-500/25"
              >
                <Plus className="w-4 h-4" />
                Nuevo Contenido
              </motion.button>

              {/* User */}
              <div className={`flex items-center gap-2 px-3 py-2 rounded-xl ${darkMode ? 'bg-gray-800/50' : 'bg-gray-100'}`}>
                <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-purple-500 to-pink-500 flex items-center justify-center">
                  <User className="w-4 h-4 text-white" />
                </div>
                <div className="text-sm">
                  <p className="font-medium">Admin</p>
                  <p className="text-xs text-gray-500">Pro Plan</p>
                </div>
              </div>
            </div>
          </header>

          {/* Content Area */}
          <div className="flex-1 overflow-y-auto p-6">
            <AnimatePresence mode="wait">
              {/* DASHBOARD VIEW */}
              {activeView === 'dashboard' && (
                <motion.div
                  key="dashboard"
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -20 }}
                  className="space-y-6"
                >
                  {/* Metrics Grid */}
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                    {[
                      { label: 'Posts Totales', value: metrics.totalPosts, icon: FileText, color: 'from-purple-500 to-pink-500', change: '+12%' },
                      { label: 'Engagement', value: `${metrics.engagement.toFixed(1)}%`, icon: Heart, color: 'from-blue-500 to-cyan-500', change: '+5.3%' },
                      { label: 'Alcance', value: `${(metrics.reach / 1000).toFixed(1)}K`, icon: Eye, color: 'from-green-500 to-emerald-500', change: '+18%' },
                      { label: 'Uptime', value: `${metrics.uptime}%`, icon: Activity, color: 'from-orange-500 to-red-500', change: '99.97%' },
                    ].map((metric, idx) => {
                      const Icon = metric.icon;
                      return (
                        <motion.div
                          key={idx}
                          initial={{ opacity: 0, y: 20 }}
                          animate={{ opacity: 1, y: 0 }}
                          transition={{ delay: idx * 0.1 }}
                          whileHover={{ y: -4, scale: 1.02 }}
                          className={`${darkMode ? 'bg-gray-900/80 border-gray-800' : 'bg-white border-gray-200'} border rounded-2xl p-5 backdrop-blur-xl`}
                        >
                          <div className="flex items-start justify-between">
                            <div>
                              <p className="text-sm text-gray-500">{metric.label}</p>
                              <p className="text-3xl font-bold mt-2">{metric.value}</p>
                              <p className="text-xs text-green-400 mt-2 flex items-center gap-1">
                                <TrendingUp className="w-3 h-3" />
                                {metric.change}
                              </p>
                            </div>
                            <div className={`w-12 h-12 rounded-xl bg-gradient-to-br ${metric.color} flex items-center justify-center shadow-lg`}>
                              <Icon className="w-6 h-6 text-white" />
                            </div>
                          </div>
                        </motion.div>
                      );
                    })}
                  </div>

                  {/* Workflow Visualization */}
                  <div className={`${darkMode ? 'bg-gray-900/80 border-gray-800' : 'bg-white border-gray-200'} border rounded-2xl p-6 backdrop-blur-xl`}>
                    <div className="flex items-center justify-between mb-6">
                      <div>
                        <h3 className="text-lg font-bold">Workflow en Tiempo Real</h3>
                        <p className="text-sm text-gray-500">Estado actual del pipeline de automatización</p>
                      </div>
                      <div className="flex items-center gap-2">
                        <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse" />
                        <span className="text-sm text-gray-400">En ejecución</span>
                      </div>
                    </div>

                    <div className="relative">
                      <svg className="absolute inset-0 w-full h-full pointer-events-none" style={{ zIndex: 0 }}>
                        {workflowNodes.map((node, idx) => {
                          if (idx === workflowNodes.length - 1) return null;
                          const next = workflowNodes[idx + 1];
                          const isActive = idx <= activeWorkflowStep;
                          return (
                            <motion.line
                              key={idx}
                              x1={`${(node.x / 1200) * 100}%`}
                              y1="50%"
                              x2={`${(next.x / 1200) * 100}%`}
                              y2="50%"
                              stroke={isActive ? 'url(#gradient)' : '#374151'}
                              strokeWidth="3"
                              strokeDasharray={isActive ? '0' : '8 4'}
                              initial={{ pathLength: 0 }}
                              animate={{ pathLength: isActive ? 1 : 0 }}
                              transition={{ duration: 0.5 }}
                            />
                          );
                        })}
                        <defs>
                          <linearGradient id="gradient" x1="0%" y1="0%" x2="100%" y2="0%">
                            <stop offset="0%" stopColor="#a855f7" />
                            <stop offset="100%" stopColor="#3b82f6" />
                          </linearGradient>
                        </defs>
                      </svg>

                      <div className="relative flex justify-between items-center" style={{ minHeight: 120 }}>
                        {workflowNodes.map((node, idx) => {
                          const isActive = idx === activeWorkflowStep;
                          const isCompleted = idx < activeWorkflowStep;
                          const icons = {
                            message: MessageCircle,
                            bot: Bot,
                            database: Database,
                            memory: MemoryStick,
                            sparkles: Sparkles,
                            mail: Mail,
                            image: ImageIcon,
                            globe: Globe,
                            share: Share2,
                          };
                          const Icon = icons[node.icon] || Circle;
                          return (
                            <motion.div
                              key={node.id}
                              animate={{
                                scale: isActive ? 1.15 : 1,
                              }}
                              className="flex flex-col items-center gap-2 z-10"
                            >
                              <div className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-all ${
                                isActive
                                  ? 'bg-gradient-to-br from-purple-600 to-blue-600 shadow-lg shadow-purple-500/50'
                                  : isCompleted
                                  ? 'bg-green-500/20 border-2 border-green-500'
                                  : darkMode ? 'bg-gray-800 border-2 border-gray-700' : 'bg-gray-100 border-2 border-gray-300'
                              }`}>
                                <Icon className={`w-6 h-6 ${
                                  isActive ? 'text-white' : isCompleted ? 'text-green-400' : 'text-gray-500'
                                }`} />
                              </div>
                              <span className={`text-xs font-medium ${isActive ? 'text-purple-400' : 'text-gray-500'}`}>
                                {node.label}
                              </span>
                              {isActive && (
                                <motion.div
                                  initial={{ opacity: 0 }}
                                  animate={{ opacity: 1 }}
                                  className="text-xs text-blue-400 flex items-center gap-1"
                                >
                                  <Loader2 className="w-3 h-3 animate-spin" />
                                  Procesando
                                </motion.div>
                              )}
                            </motion.div>
                          );
                        })}
                      </div>
                    </div>
                  </div>

                  {/* Two Column Layout */}
                  <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                    {/* Recent Activity */}
                    <div className={`${darkMode ? 'bg-gray-900/80 border-gray-800' : 'bg-white border-gray-200'} border rounded-2xl p-6 backdrop-blur-xl`}>
                      <h3 className="text-lg font-bold mb-4">Actividad Reciente</h3>
                      <div className="space-y-3">
                        {logs.slice(0, 6).map((log, idx) => (
                          <motion.div
                            key={idx}
                            initial={{ opacity: 0, x: -20 }}
                            animate={{ opacity: 1, x: 0 }}
                            transition={{ delay: idx * 0.05 }}
                            className={`flex items-start gap-3 p-3 rounded-xl ${darkMode ? 'bg-gray-800/50' : 'bg-gray-50'}`}
                          >
                            <div className={`w-2 h-2 rounded-full mt-2 flex-shrink-0 ${
                              log.type === 'success' ? 'bg-green-500' :
                              log.type === 'error' ? 'bg-red-500' :
                              log.type === 'warning' ? 'bg-yellow-500' : 'bg-blue-500'
                            }`} />
                            <div className="flex-1 min-w-0">
                              <p className="text-sm truncate">{log.message}</p>
                              <p className="text-xs text-gray-500 mt-1">{log.time}</p>
                            </div>
                          </motion.div>
                        ))}
                      </div>
                    </div>

                    {/* Platform Status */}
                    <div className={`${darkMode ? 'bg-gray-900/80 border-gray-800' : 'bg-white border-gray-200'} border rounded-2xl p-6 backdrop-blur-xl`}>
                      <h3 className="text-lg font-bold mb-4">Estado de Plataformas</h3>
                      <div className="space-y-3">
                        {platforms.filter(p => p.connected).map((platform, idx) => {
                          const Icon = platform.icon;
                          return (
                            <motion.div
                              key={platform.id}
                              initial={{ opacity: 0, x: 20 }}
                              animate={{ opacity: 1, x: 0 }}
                              transition={{ delay: idx * 0.1 }}
                              whileHover={{ x: 4 }}
                              className={`flex items-center gap-4 p-3 rounded-xl ${darkMode ? 'bg-gray-800/50 hover:bg-gray-800' : 'bg-gray-50 hover:bg-gray-100'} transition-colors cursor-pointer`}
                              onClick={() => setSelectedPlatform(platform.id)}
                            >
                              <div className={`w-10 h-10 rounded-xl bg-gradient-to-br ${platform.color} flex items-center justify-center`}>
                                <Icon className="w-5 h-5 text-white" />
                              </div>
                              <div className="flex-1">
                                <p className="font-medium text-sm">{platform.name}</p>
                                <p className="text-xs text-gray-500">{platform.posts} posts publicados</p>
