                    className={`flex-1 px-4 py-3 rounded-xl ${darkMode ? 'bg-gray-800 hover:bg-gray-700' : 'bg-gray-100 hover:bg-gray-200'} font-medium text-sm transition-colors`}
                  >
                    Cancelar
                  </button>
                  <button
                    onClick={() => {
                      setContentQueue([{
                        id: Date.now(),
                        title: newContent.title || 'Nuevo contenido',
                        platform: newContent.platform,
                        status: 'processing',
                        time: new Date().toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' }),
                        type: newContent.type,
                      }, ...contentQueue]);
                      setShowCreateModal(false);
                      setNewContent({ title: '', platform: 'Instagram', type: 'post', content: '' });
                    }}
                    className="flex-1 px-4 py-3 rounded-xl bg-gradient-to-r from-purple-600 to-blue-600 text-white font-medium text-sm shadow-lg shadow-purple-500/25"
                  >
                    <Sparkles className="w-4 h-4 inline mr-2" />
                    Generar con IA
                  </button>
                </div>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

// Workflow Node Component
const WorkflowNode = ({ title, subtitle, icon: Icon, color, darkMode, status, large }) => (
  <motion.div
    whileHover={{ scale: 1.05, y: -4 }}
    className={`${darkMode ? 'bg-gray-800/80 border-gray-700' : 'bg-white border-gray-200'} border rounded-2xl p-4 backdrop-blur-xl ${large ? 'col-span-1' : ''}`}
  >
    <div className={`w-10 h-10 rounded-xl bg-gradient-to-br ${color} flex items-center justify-center mb-3`}>
      <Icon className="w-5 h-5 text-white" />
